(function(){
  var FL = Java.loadClass("net.fabricmc.loader.api.FabricLoader");
  var MCC = Java.loadClass("com.merlinkitsune.astral_dice.init.ModCompatibilityCheck");
  var out = {};
  var loader = FL.getInstance();
  var cont = loader.getModContainer("astral_dice");
  out.modLoaded = cont.isPresent();
  var br = [];
  if (cont.isPresent()) {
    var bit = cont.get().getMetadata().getBreaks().iterator();
    while (bit.hasNext()) { br.push(String(bit.next().getModId())); }
  }
  out.breaks = br;
  out.breaksAccessories = br.indexOf("accessories") >= 0;
  out.breaksAcl = br.indexOf("accessories_compat_layer") >= 0;
  out.accessoriesLoaded = loader.isModLoaded("accessories");
  out.aclLoaded = loader.isModLoaded("accessories_compat_layer");
  out.isAccessoriesPresent = MCC.isAccessoriesPresent();
  out.isAclPresent = MCC.isAccessoriesCompatLayerPresent();
  out.isTrinketsPresent = MCC.isTrinketsPresent();
  out.trinketsLoaded = loader.isModLoaded("trinkets");
  return out;
})()
